ValidationRule.errorConditionFormula:
AND( $Setup.Salesforce_Library_Settings__c.Disable_VRs__c = false, OR( RecordType.DeveloperName = 'Customer_Complaint', RecordType.DeveloperName = 'Non_Customer_Complaint' ), OR( AND( ISPICKVAL(IDR_Is_Common__c,'Yes'), ISBLANK(IDR_Systemic_Issue_Description__c)),
AND(NOT(ISPICKVAL(IDR_Is_Common__c,'Yes')), NOT(ISBLANK(IDR_Systemic_Issue_Description__c)),IDR_Systemic_Issue_Description__c != 'None',IDR_Systemic_Issue_Description__c !='none', NOT(CONTAINS(IDR_Systemic_Issue_Description__c,'decription')))
) )
